# fx115: hiệu ứng đã tay. Rau bay vô Kho, xu lăn vô túi và số xu chạy, xuồng hàng xóm chèo đi, ghe bẹo nhổ sào, pháo hoa trên nhà. python3 fx115.py vào ra
import sys
src,dst=sys.argv[1],sys.argv[2]; s=open(src,encoding='utf-8').read()
def rep(a,b,n=1):
    global s
    assert s.count(a)==n,(a[:70],s.count(a))
    s=s.replace(a,b)
def cut(a,z,b):
    global s
    assert s.count(a)==1,a; i=s.index(a); j=s.index(z,i); s=s[:i]+b+s[j:]

CSS=""".fly.arc{transition:none;filter:drop-shadow(1.5px 0 0 #fff) drop-shadow(-1.5px 0 0 #fff) drop-shadow(0 1.5px 0 #fff) drop-shadow(0 -1.5px 0 #fff)}
#xu{font-variant-numeric:tabular-nums}
.ordgo{position:relative;overflow:hidden;margin-top:8px;border-radius:var(--r2);background:linear-gradient(#BFE0E6,#86BBCB);box-shadow:0 3px 0 #5F97AC;transition:height .28s ease,margin .28s ease,opacity .28s ease}
.ordgo b{position:absolute;left:12px;top:8px;font-family:var(--f-game);font-weight:400;font-size:17px;color:#21424F}
.ordgo .wv{position:absolute;left:-24px;right:-24px;bottom:0;height:13px;background:radial-gradient(12px 7px at 12px 13px,#6FA6B8 96%,transparent) repeat-x;background-size:24px 13px;animation:ogW 1.1s linear infinite}
@keyframes ogW{to{transform:translateX(24px)}}
.ordgo .xgw{position:absolute;left:0;bottom:5px;width:92px;height:62px;animation:ogGo 1.45s cubic-bezier(.45,0,.75,.55) .2s forwards}
.ordgo .xgw>img{position:absolute;left:0;bottom:0;width:92px;height:auto;animation:ogB .55s ease-in-out infinite alternate}
.ordgo .xgw>i{position:absolute;left:30px;bottom:38px;display:flex;animation:ogB .55s ease-in-out infinite alternate}.ordgo .xgw>i img{width:26px;height:26px;margin-left:-7px;filter:drop-shadow(0 1px 0 #fff)}
@keyframes ogGo{to{transform:translateX(560px)}}@keyframes ogB{from{transform:translateY(0) rotate(-1.5deg)}to{transform:translateY(-3px) rotate(1.5deg)}}
"""
rep(".fly{position:fixed;",CSS+".fly{position:fixed;")

# --- bay theo vòng cung, thay cho bay thẳng ---
JS=r"""function FXRM(){ return matchMedia('(prefers-reduced-motion: reduce)').matches; } function fxT(x){ return EN && typeof enT === 'function' ? enT(x) : x; }
/* bay vòng cung: nảy lên trước rồi mới lao vô đích */
function arcFly(d, x0, y0, x1, y1, o){ const N = 14, kf = [], cx = (x0 + x1) / 2 + (o.side || 0), cy = Math.min(y0, y1) - (o.lift || 80); for (let i = 0; i <= N; i++){ const t = i / N, e = t * t * (3 - 2 * t), a = 1 - e, x = a * a * x0 + 2 * a * e * cx + e * e * x1, y = a * a * y0 + 2 * a * e * cy + e * e * y1, s = t < .2 ? o.s0 + (o.sp - o.s0) * (t / .2) : o.sp + (o.s1 - o.sp) * ((t - .2) / .8); kf.push({ transform: `translate(${x - x0}px,${y - y0}px) translate(-50%,-50%) rotate(${(o.spin || 0) * t}deg) scale(${s})`, opacity: t > .88 ? (1 - t) / .12 * .5 + .5 : 1 }); } d.classList.add('arc'); d.style.left = x0 + 'px'; d.style.top = y0 + 'px'; document.body.appendChild(d); d.animate(kf, { duration: o.dur, delay: o.delay || 0, fill: 'both', easing: 'linear' }); setTimeout(() => d.remove(), o.dur + (o.delay || 0) + 30); }
/* đồng xu lăn vô túi, tới đâu kêu tới đó, số xu chạy khi đồng đầu chạm túi */
function coinFly(el, n = 1){ const a = el.getBoundingClientRect(), z = $('#xu').getBoundingClientRect(), ax = a.left + a.width / 2, ay = a.top + a.height / 2; if (FXRM()){ $('.coin').animate([{ transform: 'scale(1)' }, { transform: 'scale(1.12)' }, { transform: 'scale(1)' }], { duration: 240 }); return; } XUHOLD = performance.now() + 500; for (let i = 0; i < n; i++){ const d = document.createElement('img'), dl = i * 70, dur = 620 + R(-40, 40); d.src = UIC.coin; d.className = 'fly'; d.style.width = d.style.height = '34px'; arcFly(d, ax + R(-14, 14), ay + R(-6, 6), z.left - 14, z.top + z.height / 2, { dur, delay: dl, lift: R(50, 110), side: R(-30, 30), s0: .5, sp: 1.1, s1: .7, spin: pick([540, -540, 720]) }); setTimeout(() => { if (i < 5) sfx('tink', i); const c = $('.coin'); if (c) c.animate([{ transform: 'scale(1)' }, { transform: 'scale(1.1)' }, { transform: 'scale(1)' }], { duration: 180 }); }, dur + dl - 30); } }
/* số xu chạy thay vì nhảy thẳng tới số mới */
var XUD = null, XUTO = null, XUD0 = 0, XUS = 0, XUDUR = 0, XUHOLD = 0, XUR = 0, XUW = 0; function xuFmt(v){ return Math.round(v).toLocaleString('vi-VN'); } function xuShow(v){ const el = $('#xu'); if (XUD === null || FXRM() || document.hidden){ XUD = XUTO = v; if (XUR) cancelAnimationFrame(XUR); XUR = 0; el.textContent = xuFmt(v); return; } if (v === XUTO) return; XUTO = v; XUD0 = XUD; XUS = performance.now(); XUDUR = v > XUD ? Math.min(1100, 420 + Math.abs(v - XUD) * 2) : 380; if (!XUR) XUR = requestAnimationFrame(xuStep); } function xuStep(now){ if (now < XUHOLD && XUTO > XUD){ XUS = now; XUR = requestAnimationFrame(xuStep); return; } const k = Math.min(1, (now - XUS) / XUDUR); XUD = XUD0 + (XUTO - XUD0) * (1 - Math.pow(1 - k, 3)); if (k >= 1){ XUD = XUTO; XUR = 0; const e = $('#xu'); e.textContent = xuFmt(XUD); e.classList.remove('bump'); void e.offsetWidth; e.classList.add('bump'); return; } if (now - XUW > 45){ XUW = now; $('#xu').textContent = xuFmt(XUD); } XUR = requestAnimationFrame(xuStep); }
/* xuồng hàng xóm: giao đơn xong, đóng bảng là thấy xuồng rời bến chèo đi */
var XG = null, XGQ = 0, GGO = null, FXL = 0; function xgBuild(){ if (XG) return XG; const ps = sd, nL = LIGHTS.length, pr = ROOT, g = new T.Group(); S.add(g); ROOT = g; const h = gheTB(false); h.scale.setScalar(.82); g.add(h); const r = G(-.42, .1, 0, 0, g), AO = pick(['#3E5A7A', '#6B4A6E', '#7A4A3A']); M(cyl(.075, .1, .24, 7), AO, 0, .12, 0, { p: r }); M(sph(.07, 8, 6), '#E7B98C', 0, .3, 0, { p: r }); M(new T.ConeGeometry(.16, .09, 12), '#E3CE8A', 0, .385, 0, { p: r }); const oar = G(.05, .2, .09, 0, r); oar.rotation.x = .5; M(cyl(.012, .012, .62, 5), '#8A5D3B', -.06, -.2, 0, { p: oar, r: [0, 0, .28] }); M(box(.05, .15, .02), '#6B4529', -.15, -.52, 0, { p: oar, r: [0, 0, .28] }); M(box(.26, .13, .2), '#A8825A', .22, .09, 0, { p: g }); M(sph(.075, 7, 5), '#6E9F3A', .17, .19, .04, { p: g }); M(sph(.07, 7, 5), '#8FC84A', .28, .19, -.03, { p: g }); M(sph(.05, 7, 5), '#E07A2E', .22, .24, .02, { p: g }); g.traverse(o => { if (o.isMesh){ o.castShadow = false; o.receiveShadow = false; } }); ROOT = pr; sd = ps; LIGHTS.length = nL; g.visible = false; XG = { g, r, oar, on: false, t: 0, sp: 0 }; return XG; } function xgFlush(){ if (!XGQ || VISIT || SHEET) return; XGQ = 0; const X = xgBuild(); if (X.on) return; X.on = true; X.t = 0; X.sp = 0; X.g.position.set(bx + 1.3, WLR + .1, R0 + .4); X.said = false; X.g.visible = true; aud('gheDi');  } function fxTick(t){ const now = performance.now(), dt = Math.min(.25, (now - (FXL || now)) / 1000); FXL = now; if (!XG || !XG.on) return; const X = XG; X.t += dt; X.sp = X.t < .25 ? 0 : Math.min(1.1, (X.t - .25) * 1.2); X.g.position.x += X.sp * dt; { const u = Math.max(0, Math.min(1, (X.g.position.x - 4.6) / 2)), e = u * u * (3 - 2 * u); X.g.position.z = R0 + .4 + .22 * e; X.g.rotation.y = -.11 * Math.sin(u * Math.PI); } X.g.position.y = WLR + .1 + Math.sin(t * 1.6) * .012; X.g.rotation.z = Math.sin(t * 1.2) * .018; const st = Math.sin(X.t * 3.4); X.oar.rotation.z = st * .5; X.r.rotation.z = st * .08; if (X.sp > .3 && Math.floor((X.t - dt) * 3.4 / Math.PI) !== Math.floor(X.t * 3.4 / Math.PI)) try { splash(X.g.position.x - .35, X.g.position.z + .3); } catch (e) {} if (!X.said){ pv.copy(X.g.position).project(cam); const sx = (pv.x + 1) / 2 * innerWidth, sy = (1 - pv.y) / 2 * innerHeight; if (sx > 80 && sx < innerWidth - 80 && sy > 90 && sy < innerHeight - 40){ X.said = true; floatAt(X.g.position.x, .85, X.g.position.z, fxT('Cảm ơn con nghe!'), '#FBF7EE'); } } if (X.g.position.x > 32){ X.on = false; X.g.visible = false; } } function ggoTick(){ const g = GGO, r = GHEV.root; r.visible = true; GHEV.b.visible = false; if (g.wait){ if (SHEET) return; g.wait = false; g.x0 = r.position.x; g.t = 0; aud('gheDi'); } const dt = Math.min(.25, g.last ? (performance.now() - g.last) / 1000 : 0); g.last = performance.now(); g.t += dt; r.position.x += Math.min(1.7, g.t * .7) * dt; r.rotation.z = Math.sin(g.t * 1.6) * .015; if (r.position.x > g.x0 + 28){ r.position.x = g.x0; r.visible = false; GGO = null; } }
/* giao đơn: thẻ đơn biến thành khúc sông, xuồng chở hàng chèo qua */
function ordGoFx(o, i, el){ XGQ = 1; const card = el && el.closest('.ordr'), H = Math.max(76, card ? card.offsetHeight : 90); if (FXRM()) return; Promise.resolve().then(() => { const sub = $('#ordSub'); if (!sub) return; const L = [...document.querySelectorAll('.ordr')], at = i > 0 ? L[Math.min(i, L.length) - 1] : null, v = document.createElement('div'); v.className = 'ordgo'; v.style.height = H + 'px'; const b = document.createElement('b'); b.textContent = fxT(`${o.who} chèo xuồng về`); v.appendChild(b); const w = document.createElement('i'); w.className = 'wv'; v.appendChild(w); const g = document.createElement('div'); g.className = 'xgw'; const it = document.createElement('i'); for (const [k] of o.items.slice(0, 3)){ const m = document.createElement('img'); m.src = ICON[k]; m.alt = ''; it.appendChild(m); } const bo = document.createElement('img'); bo.src = UIC.tamban || ICON.ghe; bo.alt = ''; g.appendChild(bo); g.appendChild(it); v.appendChild(g); (at || sub).after(v); setTimeout(() => { v.style.height = '0'; v.style.marginTop = '0'; v.style.opacity = '0'; }, 1500); setTimeout(() => v.remove(), 1820); }); }
/* pháo hoa nhỏ trên mái nhà: vẽ trên lớp riêng, bắn xong gỡ liền nên không đụng tới lượt vẽ cảnh */
var FW = null; function fwGo(n){ if (FW || FXRM() || VISIT) return; const c = document.createElement('canvas'), dp = Math.min(devicePixelRatio || 1, 1.5); c.id = 'fwC'; c.style.cssText = 'position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:4'; c.width = innerWidth * dp; c.height = innerHeight * dp; document.body.appendChild(c); const big = n % 5 === 0, sh = []; for (let i = 0; i < (big ? 5 : 3); i++) sh.push({ at: .15 + i * (big ? .42 : .52), dx: i === 0 ? 0 : pick([-1, 1]) * (46 + i * 24) * (i % 2 ? 1 : -1), up: 90 + (i % 3) * 34, col: ['#FFD23F', '#FF4D2E', '#FFFFFF', '#FF7FC8', '#5FE6E0'][i % 5], st: 0 }); FW = { c, x: c.getContext('2d'), dp, sh, ps: [], t: 0, last: performance.now() }; requestAnimationFrame(fwStep); } function fwStep(now){ if (!FW) return; const F = FW, dt = Math.min(.05, (now - F.last) / 1000), x = F.x, W = innerWidth, H = innerHeight; F.last = now; F.t += dt; pv.set(2.4, 1.9, .35).project(cam); const ax = Math.max(W * .3, Math.min(W * .7, (pv.x + 1) / 2 * W)), ay = Math.max(H * .3, Math.min(H * .56, (1 - pv.y) / 2 * H)); x.setTransform(F.dp, 0, 0, F.dp, 0, 0); x.clearRect(0, 0, W, H); x.lineCap = 'round'; for (const s of F.sh){ if (F.t < s.at || s.st === 2) continue; if (!s.st){ s.st = 1; sfx('fwu'); } const k = (F.t - s.at) / .55, ky = 1 - Math.pow(1 - Math.min(1, k), 2), px = ax + s.dx, py = ay - s.up * ky; x.strokeStyle = s.col; x.globalAlpha = .9; x.lineWidth = 2.5; x.beginPath(); x.moveTo(px, py); x.lineTo(px, py + 16); x.stroke(); if (k >= 1){ s.st = 2; sfx('fwb'); for (let j = 0; j < 30; j++){ const a = j / 30 * 6.283 + R(-.1, .1), v = R(90, 195); F.ps.push({ x: px, y: py, vx: Math.cos(a) * v, vy: Math.sin(a) * v, l: R(.8, 1.2), t: 0, c: j % 4 === 0 ? '#FFF6D8' : s.col }); } s.fx = px; s.fy = py; s.ft = F.t; } } for (const s of F.sh){ if (s.ft != null && F.t - s.ft < .16){ const a = 1 - (F.t - s.ft) / .16, g = x.createRadialGradient(s.fx, s.fy, 0, s.fx, s.fy, 64); g.addColorStop(0, `rgba(255,250,225,${a * .95})`); g.addColorStop(1, 'rgba(255,240,190,0)'); x.globalAlpha = 1; x.fillStyle = g; x.beginPath(); x.arc(s.fx, s.fy, 64, 0, 6.283); x.fill(); } } for (let i = F.ps.length - 1; i >= 0; i--){ const p = F.ps[i]; p.t += dt; if (p.t >= p.l){ F.ps.splice(i, 1); continue; } p.vx *= 1 - 1.5 * dt; p.vy = p.vy * (1 - 1.5 * dt) + 70 * dt; const ox = p.x, oy = p.y; p.x += p.vx * dt; p.y += p.vy * dt; x.globalAlpha = Math.min(1, (1 - p.t / p.l) * 1.6); x.strokeStyle = p.c; x.lineWidth = 3.6; x.beginPath(); x.moveTo(ox - p.vx * .05, oy - p.vy * .05); x.lineTo(p.x, p.y); x.stroke(); } x.globalAlpha = 1; if (F.sh.every(s => s.st === 2) && !F.ps.length){ F.c.remove(); FW = null; return; } requestAnimationFrame(fwStep); } """
